{
  "units": [
    {
      "quote": "A limited-validity passport using endorsement 46 should be issued when the medical circumstance that requires eyeglasses is temporary and the applicant has urgent or emergency travel.",
      "scope_quotes": [],
      "kind": "recommendation",
      "meaning": "If the medical circumstance necessitating eyeglasses is temporary and the applicant has urgent or emergency travel, a limited-validity passport utilizing endorsement 46 should be issued."
    },
    {
      "quote": "The applicant’s expression should be natural.",
      "scope_quotes": [],
      "kind": "recommendation",
      "meaning": "The applicant's facial expression in the photograph should be natural."
    },
    {
      "quote": "Normal, unexaggerated smiles are acceptable",
      "scope_quotes": ["The applicant’s expression should be natural."],
      "kind": "permission",
      "meaning": "In passport photos, normal and unexaggerated smiles are permitted."
    },
    {
      "quote": "unusual expressions and squinting are not.",
      "scope_quotes": ["The applicant’s expression should be natural."],
      "kind": "prohibition",
      "meaning": "Unusual facial expressions and squinting are not acceptable in passport photographs."
    },
    {
      "quote": "Applicants with physical or mental disabilities, including loss of muscle control (e.g., age-related degeneration or because of a medical condition such as Bell's Palsy), may not be able to produce a natural or unexaggerated expression.",
      "scope_quotes": [],
      "kind": "statement",
      "meaning": "Applicants who have physical or mental disabilities, including muscle control loss from conditions like age-related degeneration or Bell's Palsy, might be unable to display a natural or unexaggerated facial expression."
    },
    {
      "quote": "You may accept a photograph without a natural or unexaggerated expression in these circumstances.",
      "scope_quotes": [
        "Applicants with physical or mental disabilities, including loss of muscle control (e.g., age-related degeneration or because of a medical condition such as Bell's Palsy), may not be able to produce a natural or unexaggerated expression."
      ],
      "kind": "permission",
      "meaning": "Adjudicators are permitted to accept a photograph lacking a natural or unexaggerated expression if the applicant has physical or mental disabilities preventing it."
    },
    {
      "quote": "Both of the applicant’s eyes should also be visible and open in the photograph (see the exception for infants in 8 FAM 402.1-1).",
      "scope_quotes": [],
      "kind": "recommendation",
      "meaning": "Both eyes of the applicant should be open and visible in the photograph, subject to the referenced exception for infants."
    },
    {
      "quote": "If the applicant is unable to open one or both eyes because of a medical condition, you may accept the photograph.",
      "scope_quotes": [
        "Both of the applicant’s eyes should also be visible and open in the photograph (see the exception for infants in 8 FAM 402.1-1)."
      ],
      "kind": "permission",
      "meaning": "Adjudicators are permitted to accept a photograph where one or both of the applicant's eyes are not open if the inability to open them is caused by a medical condition."
    },
    {
      "quote": "In rare cases, if it is unlikely that the closed eye(s) or exaggerated expression are because of a medical condition, you should request a medical statement signed by a medical professional/health practitioner.",
      "scope_quotes": [],
      "kind": "recommendation",
      "meaning": "In rare instances where it appears unlikely that an exaggerated expression or closed eye(s) stem from a medical condition, adjudicators should request a medical statement signed by a health practitioner or medical professional."
    },
    {
      "quote": "Processing and communications/customer service personnel at passport agencies/centers or consular section personnel should refer applications without photographs to their supervisor for guidance on processing passport applications received without photographs;",
      "scope_quotes": ["Applications received without photographs:"],
      "kind": "recommendation",
      "meaning": "When applications are received without photographs, processing and communications/customer service staff at passport agencies/centers, or consular section personnel, should refer them to their supervisor to obtain processing guidance."
    },
    {
      "quote": "You must not accept a form DS-11 or form DS-82 received without a photograph at the public counter.",
      "scope_quotes": ["Applications received without photographs:"],
      "kind": "prohibition",
      "meaning": "Personnel must not accept a Form DS-11 or Form DS-82 that is submitted at the public counter without an accompanying photograph."
    },
    {
      "quote": "See 8 FAM 1001.2 regarding importing photographs for forms DS-5504;",
      "scope_quotes": ["Applications received without photographs:"],
      "kind": "background",
      "meaning": "Provides an internal cross-reference to 8 FAM 1001.2 for procedures on importing photographs for Form DS-5504, conveying no independent substantive duty here."
    },
    {
      "quote": "Passport specialists must suspend a form DS-11 received without a photograph from an acceptance facility.",
      "scope_quotes": ["Applications received without photographs:"],
      "kind": "requirement",
      "meaning": "Passport specialists are required to suspend any Form DS-11 received from an acceptance facility lacking a photograph."
    },
    {
      "quote": "The applicant must re-execute the form DS-11 (see IRL 975-04);",
      "scope_quotes": [
        "Applications received without photographs:",
        "Passport specialists must suspend a form DS-11 received without a photograph from an acceptance facility."
      ],
      "kind": "requirement",
      "meaning": "When a Form DS-11 is suspended due to being received without a photograph from an acceptance facility, the applicant is required to re-execute the Form DS-11."
    },
    {
      "quote": "Passport specialists must suspend a form DS-82 or form DS-5504 received without a photograph (see IRL 1000-05 and IRL 1018-14).",
      "scope_quotes": ["Applications received without photographs:"],
      "kind": "requirement",
      "meaning": "Passport specialists are required to suspend any Form DS-82 or Form DS-5504 that is received without a photograph."
    }
  ]
}
